// Generates src/constants/static-md-manifest.js: the set of real static .md
// files served from public/ (excluding the generated public/md/ mirror).
//
// The proxy uses this to answer "does this .md exist?" without a per-request
// fetch. Any .md URL with no generated /md sibling (getMarkdownPath === null)
// that is NOT in this manifest is a genuine miss and gets a markdown 404.
// Because it is generated from the actual files, it can't drift.
//
// Regenerated by update:skills (skills are the most common source of change) and
// committed, so unit tests (which import the proxy) have it without a build step.
// prebuild/predev run check:static-md-manifest to fail fast if the committed copy
// is stale. Run this script (npm run generate:static-md-manifest) and commit when
// a static .md under public/ is added, removed, or renamed.

const fs = require('fs');
const path = require('path');

const PUBLIC_DIR = path.join(process.cwd(), 'public');
// public/md/ is the generated markdown mirror for content routes; those .md URLs
// are handled by the proxy's fetch branch, not this static manifest.
const EXCLUDED_DIR = path.join(PUBLIC_DIR, 'md');
const OUTPUT_FILE = path.join(process.cwd(), 'src/constants/static-md-manifest.js');

function collectMarkdownUrls(dir, urls) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (abs === EXCLUDED_DIR) continue;
      collectMarkdownUrls(abs, urls);
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      // public/foo/bar.md -> /foo/bar.md
      urls.push(`/${path.relative(PUBLIC_DIR, abs).split(path.sep).join('/')}`);
    }
  }
}

// The exact contents the manifest file should have. Shared by the generator and
// the freshness check so they can't disagree.
function buildManifestContent() {
  if (!fs.existsSync(PUBLIC_DIR)) {
    console.error(`Folder ${PUBLIC_DIR} not found`);
    process.exit(1);
  }

  const urls = [];
  collectMarkdownUrls(PUBLIC_DIR, urls);
  urls.sort();

  return `// GENERATED by src/scripts/generate-static-md-manifest.js — do not edit by hand.
// Real static .md files under public/ (excluding the generated public/md/ mirror).
// Regenerate with: npm run generate:static-md-manifest

export const STATIC_MD_PATHS = [
${urls.map((u) => `  '${u}',`).join('\n')}
];
`;
}

function generate() {
  const content = buildManifestContent();
  fs.writeFileSync(OUTPUT_FILE, content);
  const count = (content.match(/^ {2}'\//gm) || []).length;
  console.log(`Wrote ${count} static .md paths to ${path.relative(process.cwd(), OUTPUT_FILE)}`);
}

module.exports = { buildManifestContent, OUTPUT_FILE };

if (require.main === module) generate();
